import pygame

pygame.init()

PX = 1
PY = 1
W = 40
maze = []
maze_url = "https://n3s.nadesi.com/image.php?f=19.csv"

response = requests.get(maze_url)
if response.status_code == 200:
    csv_data = response.text.strip().split('\n')
    for row in csv_data:
        maze.append(list(map(int, row.split(','))))

screen = pygame.display.set_mode((40*12, 40*8))
clock = pygame.time.Clock()

def draw_tile(x, y, value):
    pygame.draw.rect(screen, (128, 128, 128), (x*W, y*W, W, W), 1)
    if value == 0:
        pygame.draw.rect(screen, (255, 255, 255), (x*W, y*W, W, W))
    elif value == 1:
        pygame.draw.rect(screen, (139, 69, 19), (x*W, y*W, W, W))

def draw_player():
    pygame.draw.rect(screen, (0, 0, 255), (PX*W+5, PY*W+30, 10, 10))
    font = pygame.font.SysFont(None, 30)
    text = font.render('♪', True, (255, 255, 255))
    screen.blit(text, (PX*W+5, PY*W+30))

def draw_maze():
    for y in range(8):
        for x in range(12):
            draw_tile(x, y, maze[y][x])
    draw_player()

def main():
    draw_maze()
    running = True
    while running:
        for event in pygame.event.get():
            if event.type == pygame.QUIT:
                running = False
            elif event.type == pygame.KEYDOWN:
                new_px = PX
                new_py = PY
                if event.key == pygame.K_UP:
                    new_py -= 1
                elif event.key == pygame.K_DOWN:
                    new_py += 1
                elif event.key == pygame.K_LEFT:
                    new_px -= 1
                elif event.key == pygame.K_RIGHT:
                    new_px += 1

