            データ[Y].append(1 + (Y * 4 + X))
    データ[3][3] = 0
    番号シャッフル実行()

def ブロック移動(Y,X):
    上下左右 = [[-1,0],[1,0],[0,-1],[0,1]]
    RY = -1
    RX = -1
    for 方向 in 上下左右:
        FY = Y + 方向[0]
        FX = X + 方向[1]
        if FY < 0 or FY > 3:
            continue
        if FX < 0 or FX > 3:
            continue
        if データ[FY][FX] == 0:
            RY = FY
            RX = FX
            break
    if RX == -1:
        return
    TMP = データ[Y][X]
    データ[Y][X] = データ[RY][RX]
    データ[RY][RX] = TMP

def 番号シャッフル実行():
    if シャッフル回数 > 30:
        return
    while True:
        Y = random.randint(0,3)
        X = random.randint(0,3)
        ブロック移動(Y,X)
        if データ[3][3] == 0:
            break
    シャッフル回数 += 1
    番号シャッフル実行()

