import random

カード一覧 = [1, 1, 2, 2, 3, 3, 4, 4]
random.shuffle(カード一覧)

while True:
    A = input(f"[1枚目]1-8の何番をめくる？{0 and 0 for card display}")
    B = input(f"[2枚目]1-8の何番をめくる？{A and 0 for card display}")

    if not A and not B:
        break

    if A == B or not A or not B:
        continue

    if カード一覧[A-1] == カード一覧[B-1]:
        print(f"⭐正解！{A}と{B}でカード表示")
        カード一覧[A-1] = 0
        カード一覧[B-1] = 0
        if sum(カード一覧) == 0:
            print("ゲームクリア！")
            break
    else:
        print(f"😭残念。{A}と{B}でカード表示")

    机 = []
    for N in range(8):
        C = "■"
        if N == A-1 or N == B-1:
            C = f"[{カード一覧[N]}]"
        elif カード一覧[N] == 0:
            C = "👌"
        机.append(C)
    print("\n".join(机))

import sys
import random

カード一覧 = [1, 1, 2, 2, 3, 3]
random.shuffle(カード一覧)
入力回数 = 1

while True:
    A = input(f"{入力回数}回目: 1-6の何番をめくる？ ")
    if not A:
        break
    B = input(f"{A}と0で机表示: 同じカードは1-6の何番目？ ")
    if not B:
        break
    if A == B:
        print("同じ位置のカードは引けません。")
        入力回数 += 1
        continue
    if カード一覧[int(A)-1] == カード一覧[int(B)-1]:
        print(f"{A}と{B}⭐正解！")
        カード一覧[int(A)-1] = 0
        カード一覧[int(B)-1] = 0
        if sum(カード一覧) == 0:
            print(f"{入力回数}回目でゲームクリア！")
            break
    else:
        print(f"{A}と{B}😭残念でした")
    入力回数 += 1

def 机表示(A, B):
    机 = []
    for N in range(6):
        if カード一覧[N] == 0:
            机.append("👌")
        elif N == int(A)-1 or N == int(B)-1:
            机.append(f"[{カード一覧[N]}]")
        else:
            机.append("■")
    return " ".join(机)

print(f"{入力回数}回目: {机表示(A, B)}")

import sys

TODO = []
保存キー = '最小TODO'
タイトル = '─────────────────────────────\n📝 最小TODO v2\n─────────────────────────────\nすべきことを入力してください（キャンセルで終了）\n数字を入力するとTODOを削除します。\n--- 以下TODO一覧 ---\n'

def 数列判定(s):
    try:
        return all(s.isdigit() for s in s.split())
    except:
        return False

def TODO項目列挙(todo_list):
    S = ''
    for i, item in enumerate(todo_list):
        S += f'📌 {i}: {item}\n'
    return S

if 保存キー in sys.stdin.read():
    TODO = eval(sys.stdin.read().split('\n')[0])

while True:
    TODO一覧 = TODO項目列挙(TODO)
    V = input(f'{タイトル}{TODO一覧}')
    if not V:
        break
    if 数列判定(V):
        for i in map(int, V.split()):
            if 0 <= i < len(TODO):
                del TODO[i]
    else:
        TODO.append(V)
    with open(保存キー, 'w') as f:
        f.write(str(TODO))

